// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum ClientCommandKind: Equatable, Hashable {

    case setSessionMode
    case sendSessionPrompt
    case submitNotificationReply
    case setSiriCurrentSession
    case setSiriDefaultSession
    case saveDefaultPrompt
    case setDefaultNotificationTargets
    case setSessionArchived
    case deleteSession
    case muteSession





}

#if compiler(>=6)
extension ClientCommandKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientCommandKind: FfiConverterRustBuffer {
    typealias SwiftType = ClientCommandKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientCommandKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .setSessionMode

        case 2: return .sendSessionPrompt

        case 3: return .submitNotificationReply

        case 4: return .setSiriCurrentSession

        case 5: return .setSiriDefaultSession

        case 6: return .saveDefaultPrompt

        case 7: return .setDefaultNotificationTargets

        case 8: return .setSessionArchived

        case 9: return .deleteSession

        case 10: return .muteSession

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClientCommandKind, into buf: inout [UInt8]) {
        switch value {


        case .setSessionMode:
            writeInt(&buf, Int32(1))


        case .sendSessionPrompt:
            writeInt(&buf, Int32(2))


        case .submitNotificationReply:
            writeInt(&buf, Int32(3))


        case .setSiriCurrentSession:
            writeInt(&buf, Int32(4))


        case .setSiriDefaultSession:
